package app.stak.nativeapp.data

import com.google.gson.JsonParser
import okhttp3.HttpUrl.Companion.toHttpUrl
import org.junit.Assert.*
import org.junit.Test
import java.time.*

class MediaIntelligenceTest {
    private fun obj(s:String)=JsonParser.parseString(s).asJsonObject
    private val base="https://dav.example/dav/".toHttpUrl()
    private fun xml(vararg rows:String)="<d:multistatus xmlns:d=\"DAV:\">${rows.joinToString("")}</d:multistatus>"
    private fun row(path:String,properties:String="<d:displayname>A.mkv</d:displayname><d:getcontentlength>100</d:getcontentlength>",status:Int=200)="<d:response><d:href>$path</d:href><d:propstat><d:prop>$properties</d:prop><d:status>HTTP/1.1 $status OK</d:status></d:propstat></d:response>"
    private fun parsed(s:String)=parseDavListing(s,base,base)
    private val item=MediaItem("one",name="A",jellyfinId="abc",jellyfinUserDataKnown=true)
    private fun torrent(files:List<TorBoxFile>)=TorBoxTorrent("1","A",1000,1f,true,"cached",files)
    @Test fun davReadsDirectoriesSizesAndEscapedNames(){val value=parsed(xml(row("/dav/A%20B.mkv"),row("/dav/folder/","<d:resourcetype><d:collection/></d:resourcetype>")));assertEquals(2,value.entries.size);assertEquals("A B.mkv",value.entries.first().relativePath);assertEquals(100L,value.entries.first().size);assertTrue(value.entries.last().directory)}
    @Test fun davCannotEscapeOriginOrConfiguredRoot(){assertTrue(parsed(xml(row("https://evil.example/A.mkv"),row("/other/A.mkv"),row("/dav/../A.mkv"),row("/dav/%2e%2e%2fA.mkv"))).entries.isEmpty())}
    @Test(expected=IllegalArgumentException::class) fun davRejectsXmlEntities(){parsed("<!DOCTYPE a [<!ENTITY x SYSTEM 'file:///etc/passwd'>]>"+xml(row("/dav/A.mkv")))}
    @Test fun davRetainsSuccessWhenOptionalPropertyIsMissing(){val value="<d:response><d:href>/dav/A.mkv</d:href><d:propstat><d:prop><d:getcontentlength>100</d:getcontentlength></d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat><d:propstat><d:prop><d:getetag/></d:prop><d:status>HTTP/1.1 404 Missing</d:status></d:propstat></d:response>";assertEquals(1,parsed(xml(value)).entries.size)}
    @Test fun davDropsFailuresAndSelfAndDuplicates(){val value=parsed(xml(row("/dav/"),row("/dav/A.mkv"),row("/dav/A.mkv"),row("/dav/B.mkv",status=403)));assertEquals(1,value.entries.size)}
    @Test fun davCapsEntries(){val value=parseDavListing(xml(row("/dav/A.mkv"),row("/dav/B.mkv")),base,base,1);assertEquals(1,value.entries.size);assertTrue(value.truncated)}
    @Test(expected=IllegalArgumentException::class) fun davRejectsEmbeddedCredentials(){davEndpoint("https://user:pass@dav.example/")}
    @Test fun davPlusIsNotSpace(){assertEquals("A+B.mkv",parsed(xml(row("/dav/A+B.mkv"))).entries.single().relativePath)}
    @Test fun missingMetadataStaysUnknown(){val r=inferredQuality("Film 2026");assertNull(r.value("resolution"));assertNull(r.value("hdr"));assertEquals(FactConfidence.UNKNOWN,r.facts.first{it.key=="hdr"}.confidence)}
    @Test fun filenameAndSizeHaveDifferentConfidence(){val r=inferredQuality("Film.2160p.REMUX.DV.HDR10.TrueHD.Atmos.7.1.mkv",200);assertEquals("2160p",r.value("resolution"));assertTrue(r.value("hdr")!!.contains("Dolby Vision"));assertEquals(FactConfidence.REPORTED,r.facts.first{it.key=="size"}.confidence);assertEquals(FactConfidence.INFERRED,r.facts.first{it.key=="hdr"}.confidence)}
    @Test fun hdr10PlusDoesNotBecomeHdr10(){val r=inferredQuality("Film.1080p.HDR10+.mkv");assertEquals("HDR10+",r.value("hdr"))}
    @Test fun verifiedReportUsesActualStreams(){val r=verifiedQuality(obj("""{"Name":"Film","MediaSources":[{"Size":1024,"Container":"mkv","MediaStreams":[{"Type":"Video","Width":3840,"Height":2160,"Codec":"hevc","BitDepth":10,"VideoRangeType":"HDR10"},{"Type":"Audio","Codec":"aac","Channels":2,"Language":"eng"}]}]}"""));assertEquals("3840 × 2160",r.value("resolution"));assertEquals("HDR10",r.value("hdr"));assertEquals(FactConfidence.VERIFIED,r.facts.first{it.key=="resolution"}.confidence);assertNull(r.value("fps"))}
    @Test fun compatibilityIsOptionalAndNeverPromisesDirectPlay(){val r=inferredQuality("Film.2160p.DV.HEVC.Atmos.mkv");assertTrue(compatibilityWarnings(r,PlaybackDevice()).isEmpty());val warnings=compatibilityWarnings(r,PlaybackDevice(enabled=true,dolbyVision="Unsupported"));assertTrue(warnings.any{it.contains("unsupported")});assertTrue(warnings.last().contains("determine direct play"))}
    @Test fun firstSnapshotCreatesNoHistoricalEvents(){val data=observeMedia(IntelligenceData(),"u",listOf(item.copy(watched=true)),1000);assertTrue(data.events.isEmpty());assertEquals(1,data.observations.size)}
    @Test fun watchedTransitionIsDeduplicated(){val base=observeMedia(IntelligenceData(),"u",listOf(item),1000);val changed=observeMedia(base,"u",listOf(item.copy(watched=true)),2000);assertEquals("Watched",changed.events.single().kind);assertEquals(1,observeMedia(changed,"u",listOf(item.copy(watched=true)),3000).events.size)}
    @Test fun progressObservationsDoNotClaimTime(){val base=observeMedia(IntelligenceData(),"u",listOf(item),1000);assertTrue(observeMedia(base,"u",listOf(item.copy(positionMs=10000)),2000).events.isEmpty());val changed=observeMedia(base,"u",listOf(item.copy(positionMs=60000)),3000);assertTrue(changed.events.single().detail.contains("not measured watch time"))}
    @Test fun pausedRecordingKeepsBaselinesWithoutEvents(){val base=observeMedia(IntelligenceData(recording=false),"u",listOf(item),1000);val next=observeMedia(base,"u",listOf(item.copy(watched=true)),2000);assertTrue(next.events.isEmpty());assertTrue(next.observations.single().played)}
    @Test fun accountsHaveIndependentBaselines(){val base=observeMedia(IntelligenceData(),"a",listOf(item),1000);val next=observeMedia(base,"b",listOf(item.copy(watched=true)),2000);assertEquals(2,next.observations.size);assertTrue(next.events.isEmpty())}
    @Test fun unknownUserDataCannotUnwatchAnItem(){val base=observeMedia(IntelligenceData(),"a",listOf(item.copy(watched=true)),1000);val next=observeMedia(base,"a",listOf(item.copy(jellyfinUserDataKnown=false)),2000);assertTrue(next.observations.single().played);assertTrue(next.events.isEmpty())}
    @Test fun otherUserSocketEventsAreIgnored(){assertNull(syncMessage("""{"MessageType":"UserDataChanged","Data":{"UserId":"other","UserDataList":[{"ItemId":"one"}]}}""","me"))}
    @Test fun socketTriggersAreNotTreatedAsAuthoritativeState(){assertEquals(setOf("one"),syncMessage("""{"MessageType":"UserDataChanged","Data":{"UserId":"me","UserDataList":[{"ItemId":"one"}]}}""","me")!!.ids);assertNull(syncMessage("invalid","me"));assertEquals(setOf("library"),syncMessage("""{"MessageType":"LibraryChanged"}""","me")!!.reasons)}
    @Test fun backoffIsBounded(){assertEquals(2000,syncBackoff(0));assertEquals(4000,syncBackoff(1));assertEquals(300000,syncBackoff(99));assertEquals(2000,syncBackoff(-1))}
    @Test fun unadvertisedSessionCannotBeControlled(){val s=serverSession(obj("""{"Id":"session","UserId":"me","NowPlayingItem":{"Name":"Film"}}"""),"me",false);assertFalse(s.canControl);assertFalse(s.canSeek);assertFalse(s.canVolume)}
    @Test fun sessionNeedsUserPermissionAndAdvertisedCapabilities(){val raw=obj("""{"Id":"s","UserId":"other","SupportsRemoteControl":true,"SupportsMediaControl":true,"NowPlayingItem":{"Name":"Film","RunTimeTicks":1000000},"PlayState":{"CanSeek":true},"Capabilities":{"SupportedCommands":["SetVolume"]},"NowPlayingQueue":[{},{}]}""");assertFalse(serverSession(raw,"me",false).canControl);val s=serverSession(raw,"me",true);assertTrue(s.canControl);assertTrue(s.canSeek);assertTrue(s.canVolume);assertTrue(s.canQueue)}
    @Test fun packRequiresEveryFileAndRejectsAmbiguousCopies(){val t=torrent(listOf(TorBoxFile("1","e1.mkv",100),TorBoxFile("2","e2.mkv",200)));val e1=DavEntry("https://x/e1","e1.mkv","e1.mkv",false,100);val e2=DavEntry("https://x/e2","e2.mkv","e2.mkv",false,200);assertFalse(matchDavPack(t,listOf(e1)).complete);assertTrue(matchDavPack(t,listOf(e1,e2)).complete);assertFalse(matchDavPack(t,listOf(e1,e2,e1.copy(url="https://x/copy"))).complete)}
    @Test fun titleMatchCannotProveIndexing(){val t=torrent(listOf(TorBoxFile("1","film.mkv",100)));val f=DavEntry("https://x/film","folder/film.mkv","film.mkv",false,100);assertFalse(indexedFileMatches(obj("""{"Name":"Same title"}"""),t,f,ZurgConnection()));assertFalse(indexedFileMatches(obj("""{"MediaSources":[{"Path":"/wrong/film.mkv","Size":100}]}"""),t,f,ZurgConnection(mountPath="/media")));assertTrue(indexedFileMatches(obj("""{"MediaSources":[{"Path":"/media/folder/film.mkv","Size":100}]}"""),t,f,ZurgConnection(mountPath="/media")))}
    @Test fun pathMappingCannotTraverse(){assertNull(mappedMediaPath(ZurgConnection(mountPath="/media"),"../secret"));assertEquals("/media/a/b.mkv",mappedMediaPath(ZurgConnection(mountPath="/media/"),"a/b.mkv"))}
    @Test fun documentedRouteMappingPreservesUser(){assertEquals("/Items/a" to "u",legacyJellyfinRoute("/Users/u/Items/a"));assertEquals("/UserItems/a/UserData" to "u",legacyJellyfinRoute("/Users/u/Items/a/UserData"));assertEquals("/UserItems/Resume" to "u",legacyJellyfinRoute("/Users/u/Items/Resume"));assertNull(legacyJellyfinRoute("/Users/AuthenticateByName"));assertNull(legacyJellyfinRoute("/Users/u/Unknown"))}
    @Test fun unknownVideoHeightIsNot4k(){val rows=libraryQuality(listOf(item,item.copy(id="two",jellyfinId="def",jellyfinVideoHeight=2160)));assertEquals(1,rows.first{it.label=="Unknown"}.count);assertEquals(1,rows.first{it.label=="2160p"}.count)}
    @Test fun monthStatsUseRealDatesAndTimezone(){val at=Instant.parse("2026-10-01T00:30:00Z").toEpochMilli();val values=monthActivity(listOf(JournalEntry(item,at,true)),LocalDate.of(2026,10,2),ZoneOffset.ofHours(-2));assertEquals(1,values.first{it.label=="2026-09"}.count);assertEquals(0,values.last().count)}
    @Test fun availableEpisodeCompletionNeedsKnownCounts(){assertEquals(0,completedAvailableSeries(listOf(item.copy(type="series",watched=true))));assertEquals(1,completedAvailableSeries(listOf(item.copy(type="series",jellyfinKnownItemCount=10,jellyfinUnplayedCount=0))))}
}
